1	"use client";
2	
3	import { useState } from "react";
4	import Link from "next/link";
5	import { retryHostingProvision, type HostingAccountView } from "@/lib/actions-hosting";
6	import { Badge, EmptyState, StatusDot } from "@/components/ui/primitives";
7	import { DeployButton } from "@/components/customer/DeployButton";
8	
9	export function HostingClient({
10	  accounts,
11	}: {
12	  accounts: HostingAccountView[];
13	}) {
14	  const [error, setError] = useState("");
15	
16	  async function retry(id: string) {
17	    setError("");
18	    // Surface a rejected retry (e.g. "isn't in a failed state") instead of a silent reload.
19	    const res = await retryHostingProvision(id);
20	    if (res.error) {
21	      setError(res.error);
22	      return;
23	    }
24	    window.location.reload();
25	  }
26	
27	  return (
28	    <div className="space-y-8">
29	      <div>
30	        <h1 className="text-xl font-semibold">Web Hosting</h1>
31	        <p className="mt-1 max-w-2xl text-sm text-slate-400">
32	          Host your website without managing a server — we run PHP, databases, email and SSL for you. Start on a free
33	          subdomain or connect your own domain.
34	        </p>
35	      </div>
36	
37	      {error && <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">{error}</div>}
38	
39	      {/* Your accounts — compact cards linking to the per-account dashboard. */}
40	      {accounts.length > 0 ? (
41	        <div className="space-y-4">
42	          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">Your hosting accounts</h2>
43	          <div className="grid gap-3 sm:grid-cols-2">
44	            {accounts.map((a) => (
45	              <AccountCard key={a.id} a={a} onRetry={() => retry(a.id)} />
46	            ))}
47	          </div>
48	        </div>
49	      ) : (
50	        <EmptyState
51	          title="No hosting accounts yet"
52	          sub="Set up an isolated hosting account — on a free subdomain or your own domain — in a couple of minutes."
53	          action={
54	            <DeployButton href="/dashboard/deploy?product=hosting">Deploy your first site</DeployButton>
55	          }
56	        />
57	      )}
58	    </div>
59	  );
60	}
61	
62	/* ---------------------------------------------------------------- card --- */
63	
64	function AccountCard({ a, onRetry }: { a: HostingAccountView; onRetry: () => void }) {
65	  const diskGB = Math.round(a.diskQuotaMB / 1024);
66	  const storage = a.diskUsedMB != null ? `${(a.diskUsedMB / 1024).toFixed(a.diskUsedMB < 1024 ? 2 : 1)} / ${diskGB} GB` : `${diskGB} GB`;
67	
68	  const body = (
69	    <>
70	      <div className="flex items-start justify-between gap-2">
71	        <div className="min-w-0">
72	          <p className="truncate font-medium text-slate-100">{a.primaryDomain}</p>
73	          <p className="mt-0.5 text-xs text-slate-500">{a.planName} · PHP {a.phpVersion}</p>
74	        </div>
75	        <StatusDot status={a.status} />
76	      </div>
77	      <div className="mt-3 flex flex-wrap items-center gap-2 text-[11px] text-slate-400">
78	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">Storage {storage}</span>
79	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxSites} extra site{a.maxSites === 1 ? "" : "s"}</span>
80	        <span className="rounded-md border border-white/[0.06] bg-white/[0.02] px-2 py-0.5">{a.maxDatabases} DB{a.maxDatabases === 1 ? "" : "s"}</span>
81	        {a.sslActive && <Badge tone="green">HTTPS</Badge>}
82	      </div>
83	    </>
84	  );
85	
86	  // A failed account can't be opened usefully — show the retry affordance inline.
87	  if (a.status === "FAILED") {
88	    return (
89	      <div className="card">
90	        {body}
91	        <div className="mt-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
92	          Setup failed{a.error ? `: ${a.error}` : ""}.{" "}
93	          <button className="font-medium underline" onClick={onRetry}>Retry setup</button>
94	        </div>
95	      </div>
96	    );
97	  }
98	
99	  return (
100	    <Link href={`/dashboard/hosting/${a.id}`} className="card card-hover block transition">
101	      {body}
102	      <p className="mt-3 text-xs font-medium text-brand-300">Manage →</p>
103	    </Link>
104	  );
105	}
