1	"use client";
2	
3	import { useEffect, useState, type ReactNode } from "react";
4	import {
5	  getHostingAccount,
6	  revealHostingSftpPassword,
7	  recheckHostingHealth,
8	  listHostingSubdomains,
9	  listHostingAddonDomains,
10	  listHostingDatabases,
11	  type HostingAccountView,
12	} from "@/lib/actions-hosting";
13	import { Badge, StatusDot } from "@/components/ui/primitives";
14	import { QuotaTile, GettingStarted, TaskFeed, type TaskView } from "./shared";
15	import { AppCredentials } from "./AppCredentials";
16	import { FileManager } from "./FileManager";
17	import { Backups } from "./Backups";
18	import { AppInstaller } from "./AppInstaller";
19	import { DatabasesPanel } from "./DatabasesPanel";
20	import { PhpSwitcher } from "./PhpSwitcher";
21	import { SubdomainsPanel } from "./SubdomainsPanel";
22	import { AddonDomainsPanel } from "./AddonDomainsPanel";
23	import { WebsitesPanel } from "./WebsitesPanel";
24	import { CronPanel } from "./CronPanel";
25	import { EmailTab } from "./EmailTab";
26	import { PlanUpgrade } from "./PlanUpgrade";
27	
28	const TABS = ["Overview", "Websites", "Files", "Databases", "Domains", "Email", "Apps", "Cron", "Backups", "Settings"] as const;
29	
30	export function HostingTabs({ account, initialTab, initialPath }: { account: HostingAccountView; initialTab?: string; initialPath?: string }) {
31	  const keys = TABS.map((t) => t.toLowerCase());
32	  const [tab, setTab] = useState<string>(
33	    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview",
34	  );
35	
36	  const active = account.status === "ACTIVE";
37	
38	  const panels: Record<string, ReactNode> = {
39	    overview: <Overview account={account} />,
40	    websites: active ? <WebsitesPanel accountId={account.id} /> : <NotReady />,
41	    files: active ? <FileManager accountId={account.id} initialPath={initialPath} /> : <NotReady />,
42	    databases: active ? <DatabasesPanel accountId={account.id} username={account.username} maxDatabases={account.maxDatabases} /> : <NotReady />,
43	    domains: active ? <DomainsTab account={account} /> : <NotReady />,
44	    email: active ? <EmailTab account={account} /> : <NotReady />,
45	    apps: active ? <AppsTab account={account} /> : <NotReady />,
46	    cron: active ? <CronPanel accountId={account.id} username={account.username} /> : <NotReady />,
47	    backups: active ? <Backups accountId={account.id} /> : <NotReady />,
48	    settings: <SettingsTab account={account} />,
49	  };
50	
51	  return (
52	    <div>
53	      <div className="mb-6 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md">
54	        {TABS.map((t) => {
55	          const k = t.toLowerCase();
56	          const isActive = tab === k;
57	          return (
58	            <button
59	              key={k}
60	              type="button"
61	              onClick={() => { setTab(k); window.history.replaceState(null, "", `?tab=${k}`); }}
62	              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
63	                isActive
64	                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
65	                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
66	              }`}
67	            >
68	              {t}
69	            </button>
70	          );
71	        })}
72	      </div>
73	      <div className="animate-fade-up">{panels[tab]}</div>
74	    </div>
75	  );
76	}
77	
78	function NotReady() {
79	  return (
80	    <div className="card py-12 text-center">
81	      <h2 className="font-semibold">Still being set up</h2>
82	      <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
83	        This account is provisioning — it usually takes under a minute. This section lights up once it’s active.
84	      </p>
85	    </div>
86	  );
87	}
88	
89	/* ------------------------------------------------------------- Overview --- */
90	
91	function Overview({ account }: { account: HostingAccountView }) {
92	  const [a, setA] = useState(account);
93	  const [sftpPw, setSftpPw] = useState<string | null>(null);
94	  const [tasks, setTasks] = useState<TaskView[]>([]);
95	  const [counts, setCounts] = useState<{ subs: number; addons: number; dbs: number } | null>(null);
96	  const [recheckBusy, setRecheckBusy] = useState(false);
97	
98	  const active = a.status === "ACTIVE";
99	  const diskGB = Math.round(a.diskQuotaMB / 1024);
100	
101	  // "Check now / Go live": flag an immediate recheck, then poll the account for
102	  // ~45s so the stepper reflects the fast-lane result (every ~30s worker tick).
103	  async function recheck() {
104	    setRecheckBusy(true);
105	    const r = await recheckHostingHealth(a.id);
106	    if (r.error) { alert(r.error); setRecheckBusy(false); return; }
107	    let tries = 0;
108	    const poll = setInterval(() => {
109	      tries++;
110	      getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {});
111	      if (tries >= 9) { clearInterval(poll); setRecheckBusy(false); }
112	    }, 5000);
113	  }
114	
115	  // Live-refresh the account (SSL status) until HTTPS is active, so the DNS→HTTPS
116	  // stepper advances on its own.
117	  useEffect(() => {
118	    if (!active || a.sslActive) return;
119	    const t = setInterval(() => { getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {}); }, 15000);
120	    return () => clearInterval(t);
121	  }, [a.id, active, a.sslActive]);
122	
123	  // Counts for the usage meters (extra sites + databases).
124	  useEffect(() => {
125	    if (!active) return;
126	    Promise.all([
127	      listHostingSubdomains(a.id).catch(() => []),
128	      listHostingAddonDomains(a.id).catch(() => []),
129	      listHostingDatabases(a.id).catch(() => []),
130	    ]).then(([subs, addons, dbs]) => setCounts({
131	      subs: subs.filter((s) => s.status !== "DELETING").length,
132	      addons: addons.filter((d) => d.status !== "DELETING").length,
133	      dbs: dbs.length,
134	    }));
135	  }, [a.id, active]);
136	
137	  async function reveal() {
138	    const res = await revealHostingSftpPassword(a.id);
139	    if (res.password) setSftpPw(res.password); else if (res.error) alert(res.error);
140	  }
141	
142	  const extraSites = counts ? counts.subs + counts.addons : 0;
143	
144	  return (
145	    <div className="space-y-6">
146	      {a.status === "FAILED" && (
147	        <div className="card border-red-500/30 text-sm text-red-300">Setup failed{a.error ? `: ${a.error}` : ""}. Contact support or retry from the hosting list.</div>
148	      )}
149	      {(a.status === "PENDING" || a.status === "PROVISIONING") && (
150	        <div className="card border-amber-500/30 text-sm text-amber-200">We’re setting up your account — this usually takes under a minute.</div>
151	      )}
152	
153	      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
154	        {/* Summary */}
155	        <div className="card">
156	          <h2 className="mb-4 font-semibold">Overview</h2>
157	          <dl className="space-y-2.5 text-sm">
158	            <div className="flex items-center justify-between"><dt className="text-slate-400">Status</dt><dd><StatusDot status={a.status} /></dd></div>
159	            <div className="flex items-center justify-between"><dt className="text-slate-400">Plan</dt><dd>{a.planName}</dd></div>
160	            <div className="flex items-center justify-between"><dt className="text-slate-400">PHP version</dt><dd className="font-mono text-xs">{a.phpVersion}</dd></div>
161	            <div className="flex items-center justify-between">
162	              <dt className="text-slate-400">Website</dt>
163	              <dd>
164	                <a href={a.sslActive ? `https://${a.primaryDomain}` : `http://${a.primaryDomain}`} target="_blank" rel="noreferrer" className="text-brand-300 hover:underline">{a.primaryDomain}</a>
165	                {a.sslActive && <Badge tone="green">HTTPS</Badge>}
166	              </dd>
167	            </div>
168	          </dl>
169	        </div>
170	
171	        {/* Free subdomain → already live (wildcard DNS); real domain → point-DNS flow */}
172	        <div className="card">
173	          <div className="mb-4 flex items-center justify-between gap-2">
174	            <h2 className="font-semibold">{a.isFreeSubdomain ? "Your website" : "Point your domain"}</h2>
175	            {active && (
176	              <button
177	                type="button"
178	                className="btn-secondary px-2.5 py-1 text-xs"
179	                disabled={recheckBusy}
180	                onClick={recheck}
181	              >
182	                {recheckBusy ? "Checking…" : a.sslActive ? "Check now" : a.isFreeSubdomain ? "Refresh" : "Go live"}
183	              </button>
184	            )}
185	          </div>
186	          {a.isFreeSubdomain ? (
187	            <p className="text-sm text-slate-400">
188	              Your free subdomain{" "}
189	              <a href={a.sslActive ? `https://${a.primaryDomain}` : `http://${a.primaryDomain}`} target="_blank" rel="noreferrer" className="font-mono text-brand-200 hover:underline">{a.primaryDomain}</a>{" "}
190	              is set up for you automatically — nothing to configure. It goes live the moment provisioning finishes, and a
191	              trusted HTTPS certificate is issued right after. Want a custom domain? Add one anytime from the{" "}
192	              <span className="text-slate-300">Domains</span> tab.
193	            </p>
194	          ) : (
195	            <p className="text-sm text-slate-400">
196	              Create an <span className="font-mono text-slate-200">A</span> record for{" "}
197	              <span className="font-mono text-slate-200">{a.primaryDomain}</span> →{" "}
198	              <span className="font-mono text-brand-200">{a.pointToA}</span>
199	              {a.pointToCname && (<>{" "}(or a <span className="font-mono text-slate-200">CNAME</span> to <span className="font-mono text-slate-200">{a.pointToCname}</span>)</>)}.
200	            </p>
201	          )}
202	          <DnsStepper account={a} />
203	        </div>
204	      </div>
205	
206	      {/* Usage meters */}
207	      {active && (
208	        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
209	          <QuotaTile
210	            label="Storage"
211	            primary={a.diskUsedMB != null ? `${(a.diskUsedMB / 1024).toFixed(a.diskUsedMB < 1024 ? 2 : 1)} of ${diskGB} GB` : `${diskGB} GB SSD`}
212	            bar={a.diskUsedMB != null ? { used: a.diskUsedMB, total: a.diskQuotaMB } : undefined}
213	            note={a.diskUsedMB == null ? "Updates automatically once your site is live" : undefined}
214	          />
215	          <QuotaTile
216	            label="Inodes (files)"
217	            primary={a.inodesUsed != null ? a.inodesUsed.toLocaleString() : "—"}
218	            note={a.inodesUsed == null ? "Measured once your site is live" : "Total files & folders"}
219	          />
220	          <QuotaTile
221	            label="Extra sites"
222	            primary={`${extraSites} of ${a.maxSites}`}
223	            bar={{ used: extraSites, total: a.maxSites }}
224	            note="Subdomains + addon domains (primary is always live)"
225	          />
226	          <QuotaTile
227	            label="Databases"
228	            primary={a.maxDatabases > 0 ? `${counts?.dbs ?? 0} of ${a.maxDatabases}` : "Not on this plan"}
229	            bar={a.maxDatabases > 0 ? { used: counts?.dbs ?? 0, total: a.maxDatabases } : undefined}
230	          />
231	        </div>
232	      )}
233	
234	      {/* SFTP access */}
235	      {active && (
236	        <div className="flex flex-wrap items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
237	          <span className="font-medium text-slate-300">SFTP</span>
238	          <span className="text-slate-400"><span className="font-mono text-slate-200">{a.username}</span>@{a.pointToA}</span>
239	          {sftpPw ? (
240	            <span className="font-mono text-brand-200">{sftpPw}</span>
241	          ) : (
242	            <button className="text-xs text-brand-300 hover:underline" onClick={reveal}>show password</button>
243	          )}
244	        </div>
245	      )}
246	
247	      {/* Getting started + task progress */}
248	      {active && <AppCredentials accountId={a.id} />}
249	      {active && <GettingStarted accountId={a.id} freeSubdomain={a.isFreeSubdomain} primaryDomain={a.primaryDomain} />}
250	      <TaskFeed accountId={a.id} active={active} onTasks={setTasks} />
251	      {/* tasks kept for the feed; referenced to avoid an unused-setter lint */}
252	      <span className="hidden">{tasks.length}</span>
253	    </div>
254	  );
255	}
256	
257	/**
258	 * DNS→HTTPS stepper driven by the REAL serve-verification the worker records
259	 * (serveHttpOk / serveHttpsOk / sslActive), so it can never claim "live" while
260	 * HTTPS actually refuses. Three overall states, per the account's measured health:
261	 *   • verified — a trusted cert is live (sslActive) and 443 answers → "HTTPS live ✓"
262	 *   • issuing  — the site answers (self-signed 443 or HTTP) but no trusted cert yet
263	 *   • dns      — nothing answers for the domain yet (DNS not pointed at us)
264	 */
265	function DnsStepper({ account }: { account: HostingAccountView }) {
266	  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
267	  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
268	  const verified = account.sslActive && account.serveHttpsOk !== false;
269	  const state: "verified" | "issuing" | "dns" | "pending" =
270	    verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";
271	
272	  const free = account.isFreeSubdomain;
273	  const steps = [
274	    { label: free ? "DNS ready" : "Point domain", done: true, hint: free ? "Set up automatically" : "Add the A record above" },
275	    {
276	      label: "Site live",
277	      done: state === "issuing" || state === "verified",
278	      hint: state === "issuing" || state === "verified" ? "Serving traffic" : state === "dns" ? "DNS not detected yet" : "Checking…",
279	    },
280	    {
281	      label: "HTTPS verified",
282	      done: state === "verified",
283	      hint: state === "verified" ? "Certificate trusted" : state === "issuing" ? "Issuing certificate" : "Auto after DNS",
284	    },
285	  ];
286	
287	  const headline =
288	    account.healthNote ??
289	    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
290	  const headlineTone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";
291	
292	  return (
293	    <div className="mt-4">
294	      <div className="flex items-center">
295	        {steps.map((s, i) => (
296	          <div key={s.label} className="flex flex-1 items-center last:flex-none">
297	            <div className="flex flex-col items-center">
298	              <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
299	                {s.done ? "✓" : i + 1}
300	              </span>
