439	export async function provisionHostingAccount(accountId: string): Promise<void> {
440	  const account = await db.hostingAccount.findUnique({ where: { id: accountId }, include: { node: true, plan: true } });
441	  if (!account || account.status !== "PENDING") return;
442	  await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PROVISIONING", error: null } });
443	
444	  if (SANDBOX || !ENABLED) {
445	    if (SANDBOX) {
446	      const pw = strongPassword();
447	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(pw), error: null } });
448	    } else {
449	      await db.hostingAccount.update({ where: { id: account.id }, data: { status: "PENDING", error: "Shared hosting is not enabled on this deployment yet." } });
450	    }
451	    return;
452	  }
453	
454	  try {
455	    const allowed = planLimits(account.plan).phpVersions;
456	    const php = allowed.includes(account.phpVersion) ? account.phpVersion : allowed[0];
457	    const sftpPassword = strongPassword();
458	    const conn = await connectNode(account.node);
459	    try {
460	      await applyIsolation(conn, { username: account.username, primaryDomain: account.primaryDomain, diskQuotaMB: account.diskQuotaMB, sftpPassword }, php);
461	    } finally {
462	      try { conn.end(); } catch { /* */ }
463	    }
464	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "ACTIVE", provisionedAt: new Date(), sftpPasswordEnc: encryptSecret(sftpPassword), error: null } });
465	    // Issue the real cert NOW instead of waiting up to a full sweep interval. A free
466	    // subdomain resolves via the *.sites wildcard the instant it's live, so certbot
467	    // succeeds immediately; a custom domain simply isn't pointed yet and is skipped
468	    // (the periodic sweep catches it once DNS lands). Best-effort — never fail a
469	    // completed provision because HTTPS issuance had a transient hiccup.
470	    await hostingSslSweep().catch((e) => console.error(`[hosting] post-provision SSL issue failed for ${account.id}`, e));
471	  } catch (e) {
472	    await db.hostingAccount.update({ where: { id: account.id }, data: { status: "FAILED", error: (e instanceof Error ? e.message : String(e)).slice(0, 300) } });
473	  }
474	}
