582	/** True once `domain` resolves (A) to the node's shared IP — DNS is pointed at us. */
583	async function domainPointsAt(domain: string, ip: string): Promise<boolean> {
584	  try {
585	    const a = await dns.resolve4(domain);
586	    return a.includes(ip);
587	  } catch {
588	    return false;
589	  }
590	}

