715	  const seenAccounts = new Set<string>();
716	  for (const sub of pendingSubs) {
717	    if (seenAccounts.has(sub.accountId)) continue;
718	    seenAccounts.add(sub.accountId);
719	    try {
720	      const a = sub.account;
721	      const u = a.username;
722	      const primary = a.primaryDomain;
723	      if (!isValidHostingDomain(primary) || !isValidUnixUsername(u)) continue;
