734	      // it can't validate and the SAN set stays stable between ticks (idempotent).
735	      const active = await db.hostingSubdomain.findMany({ where: { accountId: a.id, status: "ACTIVE" } });
736	      const resolving: typeof active = [];
737	      for (const s of active) {
738	        if (!isValidSubdomainLabel(s.label)) continue;
739	        const fqdn = `${s.label}.${primary}`;
740	        if (!isValidHostingDomain(fqdn)) continue;
741	        if (await domainPointsAt(fqdn, a.node.publicIp)) resolving.push(s);
742	      }
743	      // Nothing to do until at least one not-yet-secured subdomain resolves to us.
744	      if (!resolving.some((s) => !s.sslActive)) continue;
745	      const conn = await connectNode(a.node);
746	      try {
747	        // The account cert must already exist (the primary sweep mints it once the
748	        // primary resolves). If it doesn't yet, leave it to that sweep and retry.
749	        if ((await exec(conn, `test -s ${liveDir}/fullchain.pem && echo yes || echo no`)).out.trim() !== "yes") continue;
