751	        // + every currently-resolving sub. --cert-name pins the lineage to <primary>
752	        // so the live dir path is stable; --expand folds in the new SANs; --allow-
753	        // subset-of-names keeps a name that isn't pointed from aborting the cert;
754	        // --keep-until-expiring makes a no-op reissue idempotent when nothing changed.
755	        const keep = active.filter(
756	          (s) => (s.sslActive || resolving.includes(s)) && isValidSubdomainLabel(s.label) && isValidHostingDomain(`${s.label}.${primary}`),
757	        );
