765	        // the cert now actually carries it as a SAN (a name whose challenge failed was
766	        // dropped by --allow-subset-of-names), then serve 443 for it off the account
767	        // live dir — installNamedVhost's nginx reload also loads the expanded cert.
768	        for (const s of resolving) {
769	          if (s.sslActive) continue; // already serving HTTPS — leave it untouched
770	          const fqdn = `${s.label}.${primary}`;
771	          const covered = (await exec(conn, `openssl x509 -in ${liveDir}/fullchain.pem -noout -text 2>/dev/null | grep -qiF 'DNS:${fqdn}' && echo yes || echo no`)).out.trim() === "yes";
772	          if (!covered) { console.log(`[hosting] subdomain ${fqdn} not yet in cert — retrying next tick`); continue; }
773	          const { docroot } = subdomainPaths(u, s.label);
774	          await installNamedVhost(conn, `${u}-${s.label}`, renderSiteVhost(fqdn, docroot, `/run/php/${u}.sock`, liveDir));
