776	          console.log(`[hosting] HTTPS active for subdomain ${fqdn}`);
777	        }
778	      } finally {
779	        try { conn.end(); } catch { /* */ }
780	      }
781	    } catch (e) {
782	      console.error(`[hosting] subdomain ssl sweep ${sub.accountId} failed`, e);
783	    }
784	  }
